using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketClassifierService
{
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly VBuffer<ReadOnlyMemory<char>> _labelBuffer;

    public double MacroAccuracy { get; private set; }
    public double MicroAccuracy { get; private set; }
    public double LogLoss { get; private set; }
    public double LogLossReduction { get; private set; }

    public TicketClassifierService(string dataPath)
    {
        var mlContext = new MLContext(seed: 42);

        var dataView = mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2, seed: 42);

        var pipeline = mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
            .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        var model = pipeline.Fit(split.TrainSet);

        // Extract the label-key mapping so Score indices match category names
        var transformedData = model.Transform(split.TrainSet);
        var labelColumn = transformedData.Schema["Label"];
        labelColumn.GetKeyValues(ref _labelBuffer);

        EvaluateModel(mlContext, model, split.TestSet);

        _predictionEngine = mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(model);
    }

    private void EvaluateModel(MLContext mlContext, ITransformer model, IDataView testData)
    {
        var predictions = model.Transform(testData);
        var metrics = mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        MacroAccuracy = metrics.MacroAccuracy;
        MicroAccuracy = metrics.MicroAccuracy;
        LogLoss = metrics.LogLoss;
        LogLossReduction = metrics.LogLossReduction;

        Console.WriteLine("=== Ticket Classifier Evaluation Metrics ===");
        Console.WriteLine($"  Macro Accuracy:     {MacroAccuracy:P2}");
        Console.WriteLine($"  Micro Accuracy:     {MicroAccuracy:P2}");
        Console.WriteLine($"  Log Loss:           {LogLoss:F4}");
        Console.WriteLine($"  Log Loss Reduction: {LogLossReduction:F4}");
        Console.WriteLine("=============================================");
    }

    public TicketClassificationResult Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var labels = _labelBuffer.DenseValues().ToArray();
        var confidence = new Dictionary<string, float>();
        for (var i = 0; i < labels.Length && i < prediction.Score.Length; i++)
        {
            confidence[labels[i].ToString()] = prediction.Score[i];
        }

        return new TicketClassificationResult
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }
}

